<div class="sgd-noise">
  <canvas id="stage" width="680" height="360"></canvas>
  <div class="controls">
    <div class="ctrl-group">
      <label for="noiseScale">噪声幅度</label>
      <input type="range" id="noiseScale" min="0" max="0.5" step="0.01" value="0.3">
      <span class="val" id="noiseVal">0.30</span>
    </div>
    <div class="ctrl-group">
      <label for="stepSize">步长</label>
      <input type="range" id="stepSize" min="0.01" max="0.2" step="0.005" value="0.08">
      <span class="val" id="stepVal">0.080</span>
    </div>
    <button id="toggle">⏸ 暂停</button>
    <button id="reset">↺ 重置</button>
  </div>
  <div class="readout-row">
    <span>位置 <span class="mono" id="posX">-1.50</span>, <span class="mono" id="posY">1.20</span></span>
    <span>轨迹点 <span class="mono" id="trailCount">5</span></span>
  </div>
</div>
<script>
  (function() {
    const root = document.documentElement;
    const tok = (n) => getComputedStyle(root).getPropertyValue(n).trim();
    const canvas = document.getElementById('stage');
    const ctx = canvas.getContext('2d');
    const W = 680, H = 360;

    // state
    let paramX = -1.5;
    let paramY = 1.2;
    let noiseScale = 0.3;
    let stepSize = 0.08;
    let isRunning = true;
    let trail = [];

    // DOM refs
    const noiseSlider = document.getElementById('noiseScale');
    const noiseVal = document.getElementById('noiseVal');
    const stepSlider = document.getElementById('stepSize');
    const stepVal = document.getElementById('stepVal');
    const toggleBtn = document.getElementById('toggle');
    const resetBtn = document.getElementById('reset');
    const posXEl = document.getElementById('posX');
    const posYEl = document.getElementById('posY');
    const trailCountEl = document.getElementById('trailCount');

    // loss landscape: double valley
    // f(x,y) = 0.5*(x+1.2)^2 + 0.3*(x-1.0)^2 + 0.8*y^2 + 0.2*sin(3*x)*cos(2*y)
    // local min near (-1.2, 0), global min near (1.0, 0)
    function lossGrad(x, y) {
      const gx = (x + 1.2) + 0.6 * (x - 1.0) + 0.6 * Math.cos(3 * x) * Math.cos(2 * y);
      const gy = 1.6 * y - 0.4 * Math.sin(3 * x) * Math.sin(2 * y);
      return { gx, gy };
    }

    // update: one step of SGD with noise
    function stepSGD() {
      if (!isRunning) return;
      const { gx, gy } = lossGrad(paramX, paramY);
      const noiseX = (Math.random() - 0.5) * 2 * noiseScale;
      const noiseY = (Math.random() - 0.5) * 2 * noiseScale;
      paramX -= stepSize * (gx + noiseX);
      paramY -= stepSize * (gy + noiseY);
      // clamp to range -2..2
      paramX = Math.min(2, Math.max(-2, paramX));
      paramY = Math.min(2, Math.max(-2, paramY));
      trail.push({ x: paramX, y: paramY });
      if (trail.length > 200) trail.shift();
    }

    // draw everything
    function draw() {
      const ink = tok('--ink');
      const accent = tok('--accent');
      const line = tok('--line');
      const text2 = tok('--text2');
      const bg = tok('--bg');
      const card = tok('--card');
      const dark = root.getAttribute('data-theme') === 'lab' || root.getAttribute('data-theme')?.includes('dark');

      ctx.clearRect(0, 0, W, H);

      // map: x: -2..2 -> 60..620, y: -2..2 -> 300..60
      const mx = (x) => 60 + (x + 2) / 4 * 560;
      const my = (y) => 300 - (y + 2) / 4 * 240;

      // draw contour lines (schematic)
      ctx.strokeStyle = line;
      ctx.lineWidth = 0.8;
      ctx.globalAlpha = 0.25;
      for (let lev = 0.2; lev <= 2.0; lev += 0.3) {
        ctx.beginPath();
        let started = false;
        for (let px = -2; px <= 2; px += 0.04) {
          for (let py = -2; py <= 2; py += 0.04) {
            const v = 0.5 * (px + 1.2) ** 2 + 0.3 * (px - 1.0) ** 2 + 0.8 * py * py + 0.2 * Math.sin(3 * px) * Math.cos(2 * py);
            if (Math.abs(v - lev) < 0.08) {
              const sx = mx(px), sy = my(py);
              if (!started) { ctx.moveTo(sx, sy); started = true; }
              else ctx.lineTo(sx, sy);
            }
          }
        }
        ctx.stroke();
      }
      ctx.globalAlpha = 1.0;

      // mark local minima
      ctx.fillStyle = text2;
      ctx.font = '10px ' + tok('--mono');
      ctx.fillText('局部极小', mx(-1.2) - 20, my(0) - 8);
      ctx.fillText('全局极小', mx(1.0) - 20, my(0) - 8);
      ctx.fillStyle = text2;
      ctx.globalAlpha = 0.4;
      ctx.beginPath(); ctx.arc(mx(-1.2), my(0), 4, 0, 2 * Math.PI); ctx.fill();
      ctx.beginPath(); ctx.arc(mx(1.0), my(0), 4, 0, 2 * Math.PI); ctx.fill();
      ctx.globalAlpha = 1.0;

      // draw trail
      if (trail.length > 1) {
        ctx.strokeStyle = accent;
        ctx.lineWidth = 1.8;
        ctx.globalAlpha = 0.5;
        if (dark) {
          ctx.shadowColor = accent;
          ctx.shadowBlur = 6;
        }
        ctx.beginPath();
        for (let i = 0; i < trail.length; i++) {
          const sx = mx(trail[i].x), sy = my(trail[i].y);
          if (i === 0) ctx.moveTo(sx, sy);
          else ctx.lineTo(sx, sy);
        }
        ctx.stroke();
        ctx.shadowBlur = 0;
        ctx.globalAlpha = 1.0;
      }

      // draw current point
      const cx = mx(paramX), cy = my(paramY);
      ctx.fillStyle = accent;
      ctx.beginPath();
      ctx.arc(cx, cy, 6, 0, 2 * Math.PI);
      ctx.fill();
      ctx.strokeStyle = card;
      ctx.lineWidth = 2;
      ctx.stroke();

      // draw crosshair signature (lab theme)
      ctx.strokeStyle = text2;
      ctx.lineWidth = 0.8;
      ctx.globalAlpha = 0.3;
      ctx.setLineDash([3, 4]);
      ctx.beginPath(); ctx.moveTo(cx - 14, cy); ctx.lineTo(cx + 14, cy); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(cx, cy - 14); ctx.lineTo(cx, cy + 14); ctx.stroke();
      ctx.setLineDash([]);
      ctx.globalAlpha = 1.0;

      // corner mono readout (signature)
      ctx.fillStyle = text2;
      ctx.font = '10px ' + tok('--mono');
      ctx.fillText('x ' + paramX.toFixed(3) + '  y ' + paramY.toFixed(3), 12, 20);
      ctx.fillText('步 ' + stepSize.toFixed(3) + ' 噪 ' + noiseScale.toFixed(2), 12, 34);

      // update DOM readouts
      posXEl.textContent = paramX.toFixed(2);
      posYEl.textContent = paramY.toFixed(2);
      trailCountEl.textContent = trail.length;
    }

    // main loop
    let lastTime = performance.now();
    function loop(now) {
      const dt = Math.min((now - lastTime) / 1000, 0.03);
      lastTime = now;
      // run multiple steps per frame for visible motion
      if (isRunning) {
        const stepsPerFrame = 2;
        for (let i = 0; i < stepsPerFrame; i++) stepSGD();
      }
      draw();
      requestAnimationFrame(loop);
    }

    // interactions
    noiseSlider.addEventListener('input', () => {
      noiseScale = parseFloat(noiseSlider.value);
      noiseVal.textContent = noiseScale.toFixed(2);
    });
    stepSlider.addEventListener('input', () => {
      stepSize = parseFloat(stepSlider.value);
      stepVal.textContent = stepSize.toFixed(3);
    });
    toggleBtn.addEventListener('click', () => {
      isRunning = !isRunning;
      toggleBtn.textContent = isRunning ? '⏸ 暂停' : '▶ 继续';
    });
    resetBtn.addEventListener('click', () => {
      paramX = -1.5;
      paramY = 1.2;
      trail = [];
      // re-initialize with 5 trail points toward local min
      for (let i = 0; i < 5; i++) {
        const t = (i + 1) / 6;
        trail.push({ x: -1.5 + t * 0.3, y: 1.2 - t * 0.8 });
      }
      paramX = -1.2;
      paramY = 0.4;
      if (!isRunning) {
        isRunning = true;
        toggleBtn.textContent = '⏸ 暂停';
      }
    });

    // initial trail: 5 points from start toward local min
    trail = [];
    for (let i = 0; i < 5; i++) {
      const t = (i + 1) / 6;
      trail.push({ x: -1.5 + t * 0.3, y: 1.2 - t * 0.8 });
    }
    paramX = -1.2;
    paramY = 0.4;

    // start
    requestAnimationFrame(loop);
  })();
</script>
